using System.Reflection;
using System.Text.Json;
namespace CMCutLab;
internal static class EditorUiTest
{
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr parent,EnumProc callback,IntPtr data);
 delegate bool EnumProc(IntPtr window,IntPtr data);
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint process);
 internal static async Task Run(MainForm form,string sample){var checks=new List<string>();string path=Path.Combine(AppContext.BaseDirectory,"editor-ui-tests.json");try{
 async Task Wait(Func<bool> condition,string message){var until=DateTime.UtcNow.AddSeconds(8);while(!condition()&&DateTime.UtcNow<until)await Task.Delay(50);if(!condition())throw new Exception(message);}
 await form.OpenFile(sample);await Wait(()=>form.TestPlayer.Ready,"Embedded IPC did not connect");await Wait(()=>form.TestPlayer.Position>=0,"No position");bool embedded=false;await Wait(()=>{EnumChildWindows(form.Handle,(w,d)=>{GetWindowThreadProcessId(w,out var pid);if(pid==form.TestPlayer.VideoProcessId)embedded=true;return true;},IntPtr.Zero);return embedded;},"Video window is not a child of the editor");checks.Add("PASS mpv video window is embedded under the app window; one player panel and one timeline");
 form.TestSpace();await Wait(()=>!form.TestPlayer.Paused,"Space did not start playback");await Wait(()=>form.TestPosition>.25,"Position did not advance");form.TestSpace();await Wait(()=>form.TestPlayer.Paused,"Space did not pause playback");checks.Add("PASS Space starts and pauses embedded playback; position follows player");
 form.TestSeek(2);await Wait(()=>Math.Abs(form.TestPlayer.Position-2)<.15,"Seek did not reach 2 seconds");form.TestMarkIn();form.TestSeek(5);await Wait(()=>Math.Abs(form.TestPlayer.Position-5)<.15,"Seek did not reach 5 seconds");form.TestMarkOut();if(form.TestCutCount!=0)throw new Exception("OUT committed before Delete button");form.TestDelete();if(form.TestCutCount!=1)throw new Exception("Manual cut was not added");form.TestUndo();if(form.TestCutCount!=0)throw new Exception("Undo failed");form.TestRedo();if(form.TestCutCount!=1)throw new Exception("Redo failed");checks.Add("PASS IN/OUT creates cut, Undo removes it, Redo restores it");
 var timeline=form.TestTimeline;void Mouse(string name,int x,MouseButtons button){typeof(Timeline).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(timeline,[new MouseEventArgs(button,1,x,55,0)]);}
 Mouse("OnMouseDown",timeline.Width/4,MouseButtons.Left);Mouse("OnMouseMove",timeline.Width/2,MouseButtons.Left);Mouse("OnMouseUp",timeline.Width/2,MouseButtons.Left);double expected=form.TestSourceTime(timeline.At(timeline.Width/2));await Wait(()=>Math.Abs(form.TestPlayer.Position-expected)<.2,$"Drag scrub did not reach target; wanted={expected}, player={form.TestPlayer.Position}, editor={form.TestPosition}, paused={form.TestPlayer.Paused}");checks.Add("PASS drag mouse-down/move/up moves player to scrub target");
 await form.TestPlayer.Command(["script-message","cm-in"]);await Task.Delay(150);double outPoint=expected+3;await form.TestPlayer.Seek(outPoint);await Wait(()=>Math.Abs(form.TestPosition-outPoint)<.2,"Native playback position not synchronized");await form.TestPlayer.Command(["script-message","cm-out"]);await Task.Delay(150);form.TestDelete();await Wait(()=>form.TestCutCount==2,"Player-focused I/O commands not routed");checks.Add("PASS native player shortcut messages route IN/OUT to editor; Delete commits cut");
 if(ShuttleSpeed.FromDistance(0)!=0||ShuttleSpeed.FromDistance(100000)>128||ShuttleSpeed.FromDistance(-100000)<-128||ShuttleSpeed.FromDistance(61)<=ShuttleSpeed.FromDistance(60)||ShuttleSpeed.FromDistance(480)-ShuttleSpeed.FromDistance(479)>=ShuttleSpeed.FromDistance(320)-ShuttleSpeed.FromDistance(319))throw new Exception("Soft max x128 curve wrong");
 using(var input=new RightShuttleInput(form,[],form.TestShuttle)){
 form.TestSeek(10);await Wait(()=>Math.Abs(form.TestPlayer.Position-10)<.2,"Shuttle start seek failed");input.Begin(0,false);input.Move(160);await Wait(()=>!form.TestPlayer.Paused,"Forward shuttle did not start");await Wait(()=>form.TestPlayer.Position>10.5,"Forward shuttle did not advance");input.End();await Wait(()=>form.TestPlayer.Paused,"Right release did not stop");
 form.TestSeek(10);await Wait(()=>Math.Abs(form.TestPlayer.Position-10)<.2,"Reverse start failed");input.Begin(0,false);input.Move(-160);var reverseStart=System.Diagnostics.Stopwatch.StartNew();await Wait(()=>form.TestPlayer.Position<9.95,"Reverse shuttle did not start");if(reverseStart.Elapsed.TotalSeconds>1)throw new Exception("Reverse first movement exceeded 1 second");await Wait(()=>form.TestPlayer.Position<9.5,"Reverse shuttle did not move back");if(!form.TestPlayer.ShuttleLabel.StartsWith("REVERSE x"))throw new Exception("Direction/OSD label missing");input.End();await Wait(()=>form.TestPlayer.Paused,"Reverse release did not stop");
 form.TestSeek(10);await Wait(()=>Math.Abs(form.TestPlayer.Position-10)<.02,"Low speed start seek failed");input.Begin(0,false);var lowStart=System.Diagnostics.Stopwatch.StartNew();input.Move(-(int)Math.Ceiling(12*form.DeviceDpi/96.0));await Wait(()=>form.TestPlayer.Position<9.95,"Low speed reverse did not move");double lowMs=lowStart.Elapsed.TotalMilliseconds;if(lowMs>=1000)throw new Exception("Low speed reverse startup took "+lowMs+" ms");checks.Add($"PASS low-speed reverse first movement {lowMs:0} ms on test TS");input.Move(160);await Wait(()=>!form.TestPlayer.Paused,"Reverse to forward direction change failed");input.End();await Wait(()=>form.TestPlayer.Paused,"Direction-change release failed");}
 checks.Add("PASS shared gesture controller drives forward/reverse, first reverse movement under 1 second, OSD and release; soft x128 limit");
 var sampleJob=new RenderJob(sample,Path.Combine(AppContext.BaseDirectory,"example_AV1.mp4"),"MP4 / AV1　NVENC　6 Mbps",180);foreach(string line in new[]{"out_time_us=60000000","fps=120.0","frame=1800","total_size=45000000","progress=continue"})sampleJob.Feed(line);form.TestShowRender(sampleJob);await Task.Delay(200);form.Capture(Path.Combine(AppContext.BaseDirectory,"manual-editor-preview.png"));File.WriteAllText(path,JsonSerializer.Serialize(new{Passed=true,Checks=checks},new JsonSerializerOptions{WriteIndented=true}));
 }catch(Exception e){checks.Add(e.ToString());checks.AddRange(form.TestPlayer.Trace);File.WriteAllText(path,JsonSerializer.Serialize(new{Passed=false,Checks=checks},new JsonSerializerOptions{WriteIndented=true}));}}
}
